import math
import re

_INTEGER = re.compile(r"[+-]?(?:0|[1-9][0-9]*)\Z")


def _decode(value):
    folded = value.casefold()
    if folded == "enabled":
        return True
    if folded == "disabled":
        return False
    if _INTEGER.fullmatch(value):
        return int(value)
    if any(marker in value for marker in (".", "e", "E")):
        try:
            number = float(value)
        except ValueError:
            return value
        if math.isfinite(number):
            return number
    return value


def decode_options(options):
    if not isinstance(options, list):
        raise TypeError("options must be a list")
    result = {}
    for pair in options:
        if not isinstance(pair, list):
            raise TypeError("each option must be a list")
        if len(pair) != 2:
            raise ValueError("each option must have two elements")
        name, value = pair
        if not isinstance(name, str) or not isinstance(value, str):
            raise TypeError("names and values must be strings")
        normalized = name.strip().lower()
        if not normalized:
            raise ValueError("option name must not be empty")
        result[normalized] = _decode(value)
    return result

